import{_ as o,C as n,o as d,c as s,a3 as r,E as e}from"./chunks/framework.CZBGEXos.js";const b=JSON.parse('{"title":"Начало работы","description":"","frontmatter":{},"headers":[],"relativePath":"ru/getting-started.md","filePath":"ru/getting-started.md"}'),l={name:"ru/getting-started.md"};function i(h,t,p,c,m,g){const a=n("Screenshot");return d(),s("div",null,[t[0]||(t[0]=r('<h1 id="начало-работы" tabindex="-1">Начало работы <a class="header-anchor" href="#начало-работы" aria-label="Permalink to &quot;Начало работы&quot;">​</a></h1><p>Sentaro — это рабочее пространство для мониторинга криптовалют. Он читает общедоступные рыночные данные с Bybit, Binance, Gate.io, OKX и Hyperliquid (а также Kraken spot в <a href="/manual/ru/tools/ticks.html">Ticks</a>) и показывает их через набор специализированных инструментов.</p><p>Пользоваться им можно двумя способами, с тем же аккаунтом и теми же инструментами:</p><table tabindex="0"><thead><tr><th></th><th>Веб-версия</th><th>Приложение для Windows</th></tr></thead><tbody><tr><td>Где</td><td><a href="https://app.sentaro.trade/" target="_blank" rel="noreferrer">app.sentaro.trade</a> в любом браузере</td><td>Скачивается с <a href="https://sentaro.trade/" target="_blank" rel="noreferrer">sentaro.trade</a></td></tr><tr><td>Системы</td><td>Windows, macOS, Linux</td><td>Только Windows</td></tr><tr><td>Установка</td><td>Ничего устанавливать</td><td>Один установщик, обновляется сам</td></tr><tr><td>Раскладка</td><td>Один инструмент на экране, переключение в верхней панели</td><td>Каждый инструмент в своём окне, расположение свободное</td></tr><tr><td><a href="/manual/ru/tools/terminal.html">Terminal</a></td><td>Недоступен</td><td>Доступен (экспериментальный)</td></tr></tbody></table><p>Можно пользоваться любым или обоими одновременно. Настройки каждый хранит отдельно: веб-версия — в вашем браузере, приложение для Windows — на компьютере.</p><h2 id="аккаунт" tabindex="-1">Аккаунт <a class="header-anchor" href="#аккаунт" aria-label="Permalink to &quot;Аккаунт&quot;">​</a></h2><p>Sentaro использует аккаунт с email и паролем. При регистрации на почту отправляется 6-значный код подтверждения; введите его, чтобы подтвердить адрес, и после этого войдите. Также при регистрации нужно принять Условия предоставления услуг.</p><p>Доступ бесплатный для всех, пока Sentaro в бете. Ваш статус — <strong>Beta test</strong>: в меню аккаунта веб-версии (круглая кнопка вверху справа) и во вкладке <strong>Home</strong> приложения для Windows, вместе с вашим email и установленной версией. В приложении для Windows email по умолчанию скрыт — нажмите иконку глаза рядом, чтобы его показать.</p><div class="tip custom-block"><p class="custom-block-title">Sentaro не имеет доступа к вашим биржевым аккаунтам</p><p>Все инструменты мониторинга читают только публичные рыночные данные. Sentaro не запрашивает API-ключи бирж, не подключается к вашему аккаунту и не может выставлять ордера ни на одной из бирж, которые он отслеживает.</p><p>Единственное исключение — экспериментальный <a href="/manual/ru/tools/terminal.html">Terminal</a> в приложении для Windows, отдельный инструмент, который вы включаете сами и подключаете к Hyperliquid, Binance или Bybit своими ключами. Без вашей осознанной настройки он ничего не делает.</p></div><h2 id="веб-версия" tabindex="-1">Веб-версия <a class="header-anchor" href="#веб-версия" aria-label="Permalink to &quot;Веб-версия&quot;">​</a></h2>',10)),e(a,{src:"web-monitor",alt:"Веб-версия Sentaro с открытым Monitor",caption:"Веб-версия — открыт Monitor, под верхней панелью панель инструмента"}),t[1]||(t[1]=r('<p>Откройте <a href="https://app.sentaro.trade/" target="_blank" rel="noreferrer">app.sentaro.trade</a> и войдите.</p><h3 id="верхняя-панель" tabindex="-1">Верхняя панель <a class="header-anchor" href="#верхняя-панель" aria-label="Permalink to &quot;Верхняя панель&quot;">​</a></h3><ul><li><strong>Инструменты</strong> — Knives, Spreads, Analyzer, Monitor и Ticks. Нажмите, чтобы переключиться. Веб-версия помнит последний открытый инструмент.</li><li><strong>Поиск</strong> (<kbd>Ctrl</kbd> <kbd>K</kbd>) — откройте инструмент, его настройки, общие настройки или это руководство, набрав название.</li><li><strong>Настройки</strong> (иконка ползунков) — общие настройки: язык, акцентный цвет, графики, рисование и <a href="#всплывающие-окна-новых-листингов">всплывающие окна новых листингов</a>.</li><li><strong>Справка</strong> — ссылки на это руководство.</li><li><strong>Аккаунт</strong> — ваш email, статус беты и <strong>Sign out</strong>.</li></ul><h3 id="панель-инструмента" tabindex="-1">Панель инструмента <a class="header-anchor" href="#панель-инструмента" aria-label="Permalink to &quot;Панель инструмента&quot;">​</a></h3><p>Под верхней панелью у каждого инструмента своя панель. Чипы на ней — это <strong>быстрые фильтры</strong>: каждый показывает действующую настройку (например <code>Spread ≥ 1%</code> или <code>1m chart</code>) и открывает небольшое окно, чтобы изменить её на месте. Иконка справа открывает все настройки инструмента в боковой панели. Изменения применяются сразу.</p><h3 id="одна-вкладка-на-инструмент" tabindex="-1">Одна вкладка на инструмент <a class="header-anchor" href="#одна-вкладка-на-инструмент" aria-label="Permalink to &quot;Одна вкладка на инструмент&quot;">​</a></h3><p>Каждый инструмент получает данные с серверов Sentaro, и у одного аккаунта каждый инструмент может быть открыт только в одном месте одновременно. Если открыть тот же инструмент в другой вкладке браузера или на другом устройстве, первая покажет, что инструмент <em>открыт в другой вкладке или на другом устройстве</em>, с кнопкой <strong>Use here</strong>, чтобы вернуть его.</p><h3 id="рисование-в-полноэкранном-режиме" tabindex="-1">Рисование в полноэкранном режиме <a class="header-anchor" href="#рисование-в-полноэкранном-режиме" aria-label="Permalink to &quot;Рисование в полноэкранном режиме&quot;">​</a></h3><p>Полноэкранный график в Knives, Monitor и Spreads имеет инструменты рисования: горизонтальный луч, трендовую линию, прямоугольник, карандаш и исчезающий карандаш, а также магнит. Клавиши те же, что и в приложении для Windows (см. <a href="/manual/ru/customize/chart-colors.html">Графики и рисование</a>). Рисунки хранятся в вашем браузере для каждой монеты и биржи и видны и на графиках карточек этой монеты.</p><h2 id="приложение-для-windows" tabindex="-1">Приложение для Windows <a class="header-anchor" href="#приложение-для-windows" aria-label="Permalink to &quot;Приложение для Windows&quot;">​</a></h2><h3 id="установка" tabindex="-1">Установка <a class="header-anchor" href="#установка" aria-label="Permalink to &quot;Установка&quot;">​</a></h3><ol><li>Скачайте установщик кнопкой <strong>Download for Windows</strong> на <a href="https://sentaro.trade/" target="_blank" rel="noreferrer">sentaro.trade</a>.</li><li>Запустите <code>.exe</code>.</li></ol><h4 id="предупреждение-smartscreen" tabindex="-1">Предупреждение SmartScreen <a class="header-anchor" href="#предупреждение-smartscreen" aria-label="Permalink to &quot;Предупреждение SmartScreen&quot;">​</a></h4><p>При первом скачивании и запуске <strong>Windows Defender SmartScreen может предупредить, что приложение не распознано</strong>. Это ожидаемо и не является обнаружением вируса.</p><p>SmartScreen помечает любую новую программу, которая ещё не заработала репутацию в Microsoft — это лишь значит, что файл скачало слишком мало людей, чтобы доверять ему автоматически. Через это проходит каждое новое независимое приложение, и предупреждение исчезает само, когда число скачиваний растёт.</p><p>Чтобы его пройти:</p><ol><li>Нажмите <strong>Подробнее</strong> в окне SmartScreen.</li><li>Нажмите <strong>Выполнить в любом случае</strong>.</li><li>Это бывает только один раз — следующие запуски предупреждение не покажут.</li></ol><h3 id="первыи-запуск" tabindex="-1">Первый запуск <a class="header-anchor" href="#первыи-запуск" aria-label="Permalink to &quot;Первый запуск&quot;">​</a></h3><p>При запуске Sentaro сначала проверяет обновления, а затем просит войти.</p><h3 id="рабочее-пространство" tabindex="-1">Рабочее пространство <a class="header-anchor" href="#рабочее-пространство" aria-label="Permalink to &quot;Рабочее пространство&quot;">​</a></h3>',20)),e(a,{src:"workspace",alt:"Рабочее пространство Sentaro с несколькими открытыми окнами инструментов",caption:"Рабочее пространство Sentaro — несколько окон инструментов вокруг главного окна"}),t[2]||(t[2]=r('<p>Приложение для Windows построено вокруг одного небольшого <strong>главного окна</strong> плюс по окну на каждый инструмент.</p><p>Слева в главном окне — вертикальная панель вкладок:</p><table tabindex="0"><thead><tr><th>Вкладка</th><th>Что содержит</th></tr></thead><tbody><tr><td>Home</td><td>Аккаунт, язык, акцентный цвет, настройки графиков и рисования, всплывающие окна новых листингов</td></tr><tr><td>Knives</td><td>Настройки <a href="/manual/ru/tools/knives.html">Knives</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Spreads</td><td>Настройки <a href="/manual/ru/tools/spreads.html">Spreads</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Analyzer</td><td>Заметки <a href="/manual/ru/tools/analyzer.html">Analyzer</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Monitor</td><td>Настройки <a href="/manual/ru/tools/monitor.html">Monitor</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Terminal</td><td>Настройки <a href="/manual/ru/tools/terminal.html">Terminal</a> + кнопка <strong>Open Window</strong></td></tr><tr><td>Ticks</td><td>Настройки <a href="/manual/ru/tools/ticks.html">Ticks</a> + кнопка <strong>Open Window</strong></td></tr></tbody></table><p>Все инструменты работают одинаково: <strong>настройки живут в главном окне, а сам инструмент открывается отдельным окном.</strong> Нажмите <strong>Open Window</strong> во вкладке инструмента, чтобы его запустить. Пока то окно открыто, кнопка показывает <strong>Already Open</strong> и неактивна — у каждого инструмента может быть только одно окно.</p><p>Поскольку каждый инструмент — независимое окно, вы можете свободно менять их размер и расположение, строя нужную раскладку, а главное окно убрать в сторону.</p><p>Изменения настроек применяются вживую — открытое окно инструмента подхватывает их без перезапуска. Настройки записываются на диск автоматически.</p><h4 id="заголовок-окна" tabindex="-1">Заголовок окна <a class="header-anchor" href="#заголовок-окна" aria-label="Permalink to &quot;Заголовок окна&quot;">​</a></h4><p>Окна инструментов используют собственный заголовок Sentaro вместо виндовского. Слева в нём <code>SENTARO</code> и название активного инструмента, справа — свернуть / развернуть / закрыть. Чтобы переместить окно, тяните за любое пустое место полосы.</p><h3 id="обновления" tabindex="-1">Обновления <a class="header-anchor" href="#обновления" aria-label="Permalink to &quot;Обновления&quot;">​</a></h3><p>Приложение для Windows обновляется само. При каждом запуске оно проверяет наличие новой версии перед показом экрана входа; если она есть — скачивает, устанавливает и перезапускается автоматически. На экране загрузки при этом видно <code>Checking for updates...</code>, а затем <code>Updating to v&lt;версия&gt;...</code>.</p><p>Делать ничего не нужно. Установленная версия показана во вкладке <strong>Home</strong> как <strong>App Version</strong>. Веб-версия всегда последняя.</p><h2 id="всплывающие-окна-новых-листингов" tabindex="-1">Всплывающие окна новых листингов <a class="header-anchor" href="#всплывающие-окна-новых-листингов" aria-label="Permalink to &quot;Всплывающие окна новых листингов&quot;">​</a></h2><p>Когда монета начинает торговаться на одной из отслеживаемых бирж, появляется всплывающее окно с биржей и символом, какой бы инструмент ни был открыт:</p><ul><li><strong>Веб-версия</strong> — в правом нижнем углу страницы, пока вкладка Sentaro на экране. Листинг, пришедший, пока вкладка в фоне, позже не показывается.</li><li><strong>Приложение для Windows</strong> — в правом нижнем углу экрана, поверх других окон, даже когда Sentaro в фоне.</li></ul><p><strong>Copy</strong> копирует символ в буфер обмена. Окно держится 20 секунд и столько, сколько на нём курсор; <strong>×</strong> закрывает его. Одновременно показывается до четырёх — пятое заменяет самое старое.</p><p>О монете объявляется раз на биржу в сутки, так что символ, который биржа ненадолго убрала и вернула, не появится как новый. Окна только вживую: истории прошлых листингов нет.</p><p>Настройки — в разделе <strong>New listings</strong> общих настроек (веб) или вкладки <strong>Home</strong> (Windows):</p><ul><li><strong>Listing alert sound</strong> — звук вместе с каждым окном. Включено по умолчанию.</li><li><strong>Test pop-up</strong> — <strong>Send test</strong> показывает тестовое окно для SOLUSDT на Bybit, отправленное через сервер, чтобы проверить, что окна и звук работают.</li></ul><h2 id="звуки" tabindex="-1">Звуки <a class="header-anchor" href="#звуки" aria-label="Permalink to &quot;Звуки&quot;">​</a></h2><p>У каждого оповещения свой звук, так что вы знаете, что произошло, не глядя:</p><table tabindex="0"><thead><tr><th>Звук</th><th>Когда играет</th></tr></thead><tbody><tr><td>Rise</td><td><a href="/manual/ru/tools/knives.html">Knives</a>: монета пересекла ваш порог в %</td></tr><tr><td>Chime</td><td>Knives: монета пересекла высокий порог</td></tr><tr><td>Duo pluck</td><td><a href="/manual/ru/tools/monitor.html">Monitor</a>: достигнут порог NATR или % изменения; <a href="/manual/ru/tools/spreads.html">Spreads</a>: открылся новый спред</td></tr><tr><td>Blip</td><td><a href="/manual/ru/tools/ticks.html">Ticks</a>: крупная сделка</td></tr><tr><td>Fall</td><td>Ticks: ликвидация</td></tr><tr><td>Ding-dong</td><td><a href="#всплывающие-окна-новых-листингов">Всплывающее окно нового листинга</a></td></tr></tbody></table><p>Каждый включается или выключается в настройках своего инструмента. Браузер воспроизводит звук только после того, как вы хотя бы раз кликнули на странице.</p><h2 id="язык" tabindex="-1">Язык <a class="header-anchor" href="#язык" aria-label="Permalink to &quot;Язык&quot;">​</a></h2><p>Интерфейс Sentaro доступен на английском, украинском и русском. Переключить можно в общих настройках (веб) или во вкладке <strong>Home</strong> (Windows), вверху. Эта настройка не связана с языком, на котором вы читаете это руководство.</p><h2 id="акцентныи-цвет" tabindex="-1">Акцентный цвет <a class="header-anchor" href="#акцентныи-цвет" aria-label="Permalink to &quot;Акцентный цвет&quot;">​</a></h2><p>В общих настройках (веб) или во вкладке <strong>Home</strong> (Windows) ряд цветовых образцов задаёт акцентный цвет для всего приложения: Amber (по умолчанию), Green, Blue, Purple, Red, Teal, Pink и White. Он действует во всех инструментах.</p><p>Это отдельно от цветов свечей и метрик — о них см. <a href="/manual/ru/customize/chart-colors.html">Графики и рисование</a>.</p><h2 id="сообщения-об-ошибках" tabindex="-1">Сообщения об ошибках <a class="header-anchor" href="#сообщения-об-ошибках" aria-label="Permalink to &quot;Сообщения об ошибках&quot;">​</a></h2><p>Когда что-то идёт не так — поток данных отключился, окно не открылось, сохранённые настройки не загрузились — в правом нижнем углу появляется короткое сообщение. Оно исчезает само через несколько секунд, или нажмите <strong>×</strong>, чтобы закрыть его. Одно и то же сообщение показывается не чаще раза в 15 секунд, так что соединение, которое раз за разом переподключается, не засыплет экран.</p><p>Если ошибка возвращается снова и снова, напишите о ней в <a href="https://t.me/sentaro_trade" target="_blank" rel="noreferrer">Telegram-группу</a> с точным текстом.</p><h2 id="где-получить-помощь" tabindex="-1">Где получить помощь <a class="header-anchor" href="#где-получить-помощь" aria-label="Permalink to &quot;Где получить помощь&quot;">​</a></h2><p>Сообщения об ошибках и пожелания — в <a href="https://t.me/sentaro_trade" target="_blank" rel="noreferrer">группу Telegram</a>. Это самый быстрый способ получить прямой ответ.</p>',32))])}const f=o(l,[["render",i]]);export{b as __pageData,f as default};
